{
  "case_id": "C07",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The open problem",
      "narration": "Roughly one third of patients with major depressive disorder don't respond to a first-line SSRI. Could a blood test hint at who?",
      "on_screen": "Title card: 'Roughly one third do not respond to a first-line SSRI'",
      "claim_refs": [
        "CL05"
      ]
    },
    {
      "beat": "Why IL-6",
      "narration": "Blood markers of inflammation have repeatedly been associated with poorer antidepressant response, and interleukin-6 is the most frequently reported.",
      "on_screen": "Label: IL-6, measurable on routine platforms; caption 'prior associations, mechanism not settled'",
      "claim_refs": [
        "CL06",
        "CL04"
      ]
    },
    {
      "beat": "What the study did",
      "narration": "An observational study of 512 adults with major depressive disorder, recruited from four secondary-care services, measured IL-6 a single time, at baseline.",
      "on_screen": "Study card: observational cohort, 512 adults with major depressive disorder recruited from four secondary-care services, single baseline high-sensitivity IL-6 measurement",
      "claim_refs": [
        "CL01",
        "CL08"
      ]
    },
    {
      "beat": "The headline numbers",
      "narration": "At 12 weeks, 34% of the highest IL-6 tertile responded, versus 58% of the lowest: adjusted odds ratio 0.41, 95% CI 0.27-0.63.",
      "on_screen": "Two bars: highest tertile 34%, lowest tertile 58%; below them 'adjusted odds ratio 0.41 (95% CI 0.27-0.63)', endpoint: response at 12 weeks",
      "claim_refs": [
        "CL01"
      ]
    },
    {
      "beat": "Consistency and drop-out",
      "narration": "Analysing IL-6 as a continuous measure in the same cohort gave a consistent estimate: adjusted odds ratio per doubling 0.72, 95% CI 0.61-0.85. Loss to follow-up was 9%.",
      "on_screen": "Sensitivity analysis, same 512 participants: adjusted odds ratio per doubling of IL-6 0.72 (95% CI 0.61-0.85); loss to follow-up 9%",
      "claim_refs": [
        "CL02",
        "CL07"
      ]
    },
    {
      "beat": "Association, not cause",
      "narration": "But this is association, not cause: a signpost, not a lever. IL-6 wasn't manipulated, each person's IL-6 was measured only once, at baseline, the tertile cut-points came from this cohort, and which SSRI people took, and at what dose, was left to their clinician.",
      "on_screen": "Signpost icon beside a crossed-out lever; bullets: not manipulated, single baseline IL-6 measurement, cohort-specific tertiles, SSRI choice and dose were left to the treating clinician, no multiplicity correction",
      "claim_refs": [
        "CL01",
        "CL08",
        "CL09"
      ]
    },
    {
      "beat": "The proposed mechanism",
      "narration": "The authors propose a tryptophan-to-kynurenine explanation, but no kynurenine metabolites were measured, and the peripheral-to-central mechanism isn't settled.",
      "on_screen": "Dashed, question-marked arrow from IL-6 to brain; caption 'proposed, untested: kynurenine metabolites measured: None'",
      "claim_refs": [
        "CL03",
        "CL04"
      ]
    },
    {
      "beat": "Where that leaves us",
      "narration": "So it's a candidate marker that might one day flag patients for whom an SSRI is a lower-yield first choice, not a validated test today.",
      "on_screen": "Closing card: 'candidate stratification marker, suggested but not tested here'",
      "claim_refs": [
        "CL09"
      ]
    }
  ]
}
